// Resolve the requested language from whichever shape the message has,
// then hard-whitelist it. The result is passed to the exec node as the
// argument to --lang, so an unvalidated value here would be a command
// argument -- keep the whitelist.
const ALLOWED = ['en', 'hi', 'hinglish'];

let lang;
if (typeof msg.payload === 'string' && msg.payload.trim()) {
    lang = msg.payload;
} else if (msg.payload && typeof msg.payload === 'object' && msg.payload.lang) {
    lang = msg.payload.lang;
}
if (!lang && msg.req && msg.req.query && msg.req.query.lang) {
    lang = msg.req.query.lang;
}
if (!lang) {
    lang = msg.lang || env.get('VOICE_LANG') || 'en';
}

lang = String(lang).toLowerCase().trim();
if (ALLOWED.indexOf(lang) === -1) {
    node.warn('unsupported lang "' + lang + '", falling back to en');
    lang = 'en';
}

msg.lang = lang;
msg.payload = lang;
return msg;

// server_brain.py prints exactly one speakable sentence on stdout and
// exits 0 even on failure, so the Echo is never left silent. Still guard
// against an empty stdout (container OOM, script deleted, ...).
const speech = String(msg.payload || '').trim();

msg.payload = speech || 'Sorry, I could not read the download status right now.';
msg.speech = msg.payload;
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
return msg;
